    p.assemblyTarget??=(s.kits??[]).some(k=>k.stage==='ORGANS'&&k.canConsume)?22:(s.kits??[]).some(k=>k.stage==='CELLS'&&k.canConsume)?16:4;const target=p.assemblyTarget;
    host.append(field('What are you assembling?',select([...FUNCTION_NAMES.map((name,i)=>[i+1,`Cell C${String(i+1).padStart(2,'0')} · ${name}`]),...ORGAN_ROLES.map((roles,i)=>[16+i,`Organ O${String(i+1).padStart(2,'0')} · ${roles.length} cells`]),[22,'Complete digital organism · 6 organs']],target,v=>{p.assemblyTarget=Number(v);p.assemblyInputs=null;render();})));
