  const filters=row();for(const scope of ['ALL','COMPONENT','CELL','ORGAN','BIO'])filters.append(button(({ALL:'All specimens',COMPONENT:'Components',CELL:'Cells',ORGAN:'Organs',BIO:'Organisms'})[scope],()=>{p.assetScope=scope;p.workLimit=12;render();},{active:(p.assetScope??'ALL')===scope}));host.append(filters);
